              "rule_id",
              "persona",
              "goal",
              "journey",
              "steps",
              "cells",
              "route_pattern",
              "friction_target",
              "observed_friction",
              "evidence",
              "basis",
              "proposed_improvement",
              "expected_benefit",
              "trade_offs",
              "priority",
              "confidence",
              "verification_status",
              "rationale",
